<?php require_once '../includes/auth.php';require_once '../config/koneksi.php';$data=$conn->query('SELECT * FROM jenis_pembayaran ORDER BY id_jenis DESC');$page_title='Jenis Pembayaran';$active='jenis';$prefix='../';include '../includes/header.php';?><div class="page-heading"><div><h1>Jenis Pembayaran</h1><p>Atur kategori biaya administrasi beserta nominal standar.</p></div><a class="btn btn-primary" href="tambah.php"><i class="bi bi-plus-lg me-1"></i>Tambah Jenis</a></div><div class="panel"><div class="panel-head"><strong>Daftar Jenis Pembayaran</strong><span class="text-secondary small"><?= $data->num_rows ?> kategori</span></div><div class="table-responsive"><table class="table"><thead><tr><th>No</th><th>Nama Jenis</th><th>Tingkat Berlaku</th><th>Nominal Standar</th><th>Keterangan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php $i=1;while($r=$data->fetch_assoc()):?><tr><td><?= $i++ ?></td><td><strong><?= e($r['nama_jenis']) ?></strong></td><td><span class="badge-soft"><?= e(($r['tingkat']??'Semua Tingkat')==='Semua Tingkat'?'Semua Tingkat':'Kelas '.$r['tingkat']) ?></span></td><td class="fw-bold"><?= rupiah($r['nominal']) ?></td><td><?= e($r['keterangan']?:'-') ?></td><td><span class="badge <?= $r['status']==='aktif'?'text-bg-success':'text-bg-secondary' ?>"><?= e(ucfirst($r['status'])) ?></span></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="edit.php?id=<?= $r['id_jenis'] ?>"><i class="bi bi-pencil"></i></a> <a class="btn btn-sm btn-outline-danger" data-confirm="Hapus jenis pembayaran ini?" href="hapus.php?id=<?= $r['id_jenis'] ?>"><i class="bi bi-trash"></i></a></td></tr><?php endwhile;?></tbody></table></div></div><?php include '../includes/footer.php';?>